})

// --- Per-route override ---

test('route-level handlerTimeout overrides server default', async t => {
  t.plan(4)
  const fastify = Fastify({ handlerTimeout: 5000 })

  fastify.get('/slow', { handlerTimeout: 50 }, async () => {
    await new Promise(resolve => setTimeout(resolve, 500))
    return 'too late'
  })

